(function(){
  const escape=text=>String(text??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const icon=name=>`<svg class="icon" aria-hidden="true"><use href="#${name}"/></svg>`;
  const number=n=>new Intl.NumberFormat('pl-PL').format(n);
  const brandSlug=brand=>({'Mercedes-Benz':'mercedes',Volkswagen:'volkswagen',Nissan:'nissan',Opel:'opel',Peugeot:'peugeot',Renault:'renault',Daihatsu:'daihatsu',Jaguar:'jaguar',Audi:'audi'}[brand]);
  const photo=car=>car.image?`<img src="${escape(car.image)}" alt="${escape(car.brand+' '+car.name)}" loading="lazy" width="700" height="500">`:`<div class="photo-unavailable"><img src="assets/brands/${brandSlug(car.brand)}.svg" alt=""><span>Galeria w ogłoszeniu OTOMOTO ${icon('arrow-up')}</span></div>`;
  const price=car=>car.price?`${number(car.price)} <span>zł</span>`:'Zapytaj o cenę';
  const priceLabel=car=>car.priceOrigin==='instagram'?'CENA Z PUBLIKACJI':car.price?'CENA Z OGŁOSZENIA':'CENA DO POTWIERDZENIA';
  const card=car=>`<article class="car-card"><div class="car-image"><a class="car-photo-link" href="samochod-${escape(car.id)}.html" aria-label="Zobacz ${escape(car.brand+' '+car.name)}">${photo(car)}</a><span class="car-tag${car.status==='listed'?'':' tag-dark'}">${car.availability==='reserved'?'REZERWACJA':car.status==='listed'?'OFERTA OTOMOTO':'Z INSTAGRAMA'}</span><a class="car-instagram" href="${escape(car.source)}" target="_blank" rel="noopener noreferrer" aria-label="Zobacz źródłowe ogłoszenie">${icon(car.status==='listed'?'arrow-up':'instagram')}</a></div><div class="car-body"><span class="car-brand">${escape(car.brand)}</span><h3><a href="samochod-${escape(car.id)}.html">${escape(car.name)}</a></h3><p class="car-subtitle">${escape(car.subtitle)}</p><div class="car-specs"><span>${icon('calendar')}${car.year}</span><span>${icon('gauge')}${car.mileage?number(car.mileage)+' km':'Przebieg: zapytaj'}</span><span>${icon('fuel')}${escape(car.fuel)}</span></div><div class="car-bottom"><div class="car-price"><small>${priceLabel(car)}</small><strong>${price(car)}</strong></div><a class="car-details" href="samochod-${escape(car.id)}.html" aria-label="Szczegóły ${escape(car.brand+' '+car.name)}">${icon('arrow-up')}</a></div><p class="car-availability">${car.availability==='reserved'?'Zarezerwowany — zapytaj o status':car.status==='listed'?'Oferta sprawdzona 09.11.2026':'Potwierdź aktualną dostępność'}</p></div></article>`;
  window.IGUI={escape,icon,number,card,photo,price,priceLabel,brandSlug};
})();
